  /// Auto-compaction after each completed run (CLI parity): the shared
  /// [AutoCompactor] in core drives the multi-pass loop + smol→main
  /// fallback + transient retry. This wrapper resolves the host wiring
  /// (gh-1077: the same shared resolution the CLI computes through),
  /// builds the per-host smol/main summarizers, and surfaces failures
  /// in-chat instead of silently no-oping.
  Future<bool> _maybeAutoCompact({bool postRun = false}) async {
    // GOAL #2394 (D6/E37): tags ride the wire only under the structured
    // engine — re-resolved per run like the engine itself (the Settings
    // picker edits apply without a restart).
    _agent.recordTagsEnabled =
        _appCompactionEngine == CompactionEngine.structured;
    final wiring = _compactionWiring;
    handOverTrigger.hysteresis.turns =
        wiring.handOverHysteresisTurns ?? handOverHysteresisTurnsDefault;
    if (_session == null || !wiring.enabled) return false;
    final conversationWindow = wiring.conversationWindow;
    if (conversationWindow <= 0) return false;
    final settings = wiring.settings;
    // The same request-size basis as the loop's over-window guard and the
    // CLI's compaction gate: transcript estimate PLUS the system-prompt /
    // tool-schema overhead when no provider-usage anchor prices them in —
    // the threshold must trip on what the next request actually carries.
    final transcriptTokens = estimateRequestTokens(
      _agent.state.messages,
      systemPrompt: _agent.state.systemPrompt,
        model: config.toModel(),
        systemPrompt: _composeSystemPrompt(config),
        // The loop's over-window guard measures against the effective
        // (capped) window, and issue #387 relief gives a hard overflow ONE
        // synchronous compaction before the turn dies — CLI parity.
        contextWindowCap: _contextWindowCap,
        overWindowRelief: (overWindow) => _relieveOverWindow(overWindow),
      ),
    );
    _toolRegistry = stack.registry;
    _agent = stack.agent;
    // GOAL #2394 (D6/E37): record tags on the wire only under the
    // structured engine; re-synced at every auto-compaction run.
    _agent.recordTagsEnabled =
        _appCompactionEngine == CompactionEngine.structured;
    // Boot beacon for the office pane e2e (issue #182): proves the app
    // booted WITH the mail surface when running as the Outlook taskpane.
    if (officeApi != null) {
      debugPrint('[fah] office: outlook.* tools registered (office host)');
    }

    // gh-1409: publish the boot discovery's enabled skills — the pin
    // registry's source set. Derived state (P2): re-published on consent
    // and toggle changes; without this the app host's pin mechanism is a
    // silent no-op until a settings change.
    _agent.operativeSkills = List.of(_bootOperativeSkills);

