/// [stripRecordTags] works on COMPLETE texts; a live delta stream must not
/// show the tag's own bytes even transiently — a prefix split across
/// deltas (`m14` then `82 При…`) would flicker `m14` onto the screen
/// before the tag completed. This filter classifies each LINE START
/// before any of its bytes are emitted: it holds only the undecided `m`
/// + digits prefix, swallows it (plus the tag's trailing spaces) when a
/// space confirms the tag, and releases the bytes verbatim the moment
/// they cannot be a tag. A line start re-arms the classification, so
/// every line of a multi-line reply is judged independently — the same
/// semantics as [stripRecordTags]'s `^m\d+ +` (the gh-2412 contract).
/// [flush] emits an undecided tail verbatim: a text ending `m2` with no
/// trailing space never matched the rule, so the bytes are the model's
/// own words — then resets, so the next message classifies from a fresh
/// line.
final class RecordTagEchoStreamFilter {
  StringBuffer? _pending;

  /// Streams one delta; returns the text safe to render now (possibly
  /// empty — bytes held back while a line start is still undecided).
  String push(String delta) {
    final out = StringBuffer();
    for (var i = 0; i < delta.length; i++) {
      final ch = delta[i];
      final pending = _pending;
      if (pending == null) {
        // A `m` at a line start opens a candidate tag (a `\n` re-arms:
        // the emit path closes the previous classification).
        if (ch == 'm' && _atLineStart) {
          _pending = StringBuffer(ch);
        } else {
          if (ch == '\n') _atLineStart = true;
          out.write(ch);
