/// gh-2472 — the model-facing `m<N>` record tags a model echoes into its
/// replies never reach the app's chat: streamed deltas are sanitized at
/// the ingestion seam (a tag split across deltas `m14` + `82 При…` never
/// flickers a fragment into the live bubble), and the finalized row
/// renders the clean text.
library;

import 'dart:async';

import 'package:fa/services/agent_service.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_test/flutter_test.dart';

AssistantMessage _msg(List<ContentBlock> content, Model m) => AssistantMessage(
  content: content,
  api: m.api,
  provider: m.provider,
  model: m.id,
  usage: Usage.zero,
  stopReason: StopReason.stop,
  timestamp: DateTime.now(),
);

AgentService _service(Future<void> Function(void Function()) body) {
  return AgentService(
    agent: Agent(
      model: Model(
        id: 'test-model',
        api: 'test-api',
        provider: 'test',
        baseUrl: 'https://example.com',
        contextWindow: 100000,
        maxTokens: 4096,
      ),
      systemPrompt: 'You are Fa.',
      toolRegistry: ToolRegistry(const []),
    ),
    env: MemoryExecutionEnv(),
    sessionsRoot: '/sessions',
    config: AgentConfig(
      providerKind: 'test',
      modelId: 'test-model',
      baseUrl: 'https://example.com',
      apiKey: '',
    ),
  );
}

void main() {
  testWidgets('a tag split across deltas never flickers into the bubble', (
    tester,
  ) async {
    final firstDeltaLanded = Completer<void>();
    final releaseSecond = Completer<void>();
    // The turn streams `m1482 Принято…` in two fragments: the first lands
    // alone (the old bug painted `m14` here), the gate holds the stream
    // so the test can observe the live bubble before the rest arrives.
    Future<void> streamFn(void Function(AgentService) push) async {
      push;
    }

    // The stream plumbing below mirrors agent_service_thinking_test.dart:
    // a fake stream function whose events are pushed by the test body.
    AssistantMessageEventStream? live;
    Future<AssistantMessageEventStream> fn(Model model, Context context,
        {cancelToken}) async {
      final stream = AssistantMessageEventStream();
      live = stream;
      return stream;
    }

    final service = AgentService(
      agent: Agent(
        model: Model(
          id: 'test-model',
          api: 'test-api',
          provider: 'test',
          baseUrl: 'https://example.com',
          contextWindow: 100000,
          maxTokens: 4096,
        ),
        systemPrompt: 'You are Fa.',
        streamFunction: fn,
        toolRegistry: ToolRegistry(const []),
      ),
      env: MemoryExecutionEnv(),
      sessionsRoot: '/sessions',
      config: AgentConfig(
        providerKind: 'test',
        modelId: 'test-model',
        baseUrl: 'https://example.com',
        apiKey: '',
      ),
    );

    final run = tester.runAsync(() async {
      final sending = service.sendText('question');
      // Wait until the stream function was called and the live edge is
      // wired, then drive the deltas through it.
      for (var i = 0;
          i < 5000 && (live == null || service.messages.isEmpty);
          i++) {
        await Future<void>.delayed(const Duration(milliseconds: 2));
      }
      final partial1 = _msg([const TextContent(text: 'm1482 Принято…')],
          service.agent.state.model);
      live!
        ..push(StartEvent(partial: _msg(const [], service.agent.state.model)))
        ..push(
          TextDeltaEvent(
            contentIndex: 0,
            delta: 'm14',
            partial: _msg(
              [const TextContent(text: 'm14')],
              service.agent.state.model,
            ),
          ),
        );
      firstDeltaLanded.complete();
      await releaseSecond.future;
      live!
        ..push(
          TextDeltaEvent(
            contentIndex: 0,
            delta: '82 Принято…',
            partial: partial1,
          ),
        )
        ..push(DoneEvent(reason: StopReason.stop, message: partial1));
      live!.end();
      await sending;
      await service.waitForIdle();
    });
    await tester.pump();
    await firstDeltaLanded.future;
    // The held fragment must not have flickered into the live bubble.
    await tester.pump();
    final streamedRow = service.messages
        .where((m) => m.role == 'assistant')
        .firstOrNull;
    expect(streamedRow, isNotNull);
    expect(
      streamedRow!.content.contains('m14'),
      isFalse,
      reason:
          'the echoed tag fragment flickered: "${streamedRow.content}"',
    );
    releaseSecond.complete();
    await run;
    await tester.pump();

    final answer = service.messages
        .where((m) => m.role == 'assistant')
        .firstOrNull;
    expect(answer, isNotNull);
    expect(answer!.content, 'Принято…');
  });

  testWidgets('an undecided tail survives the finalize flush', (tester) async {
    final service = _service((_) {});
    AssistantMessageEventStream? live;
    Future<AssistantMessageEventStream> fn(Model model, Context context,
        {cancelToken}) async {
      final stream = AssistantMessageEventStream();
      live = stream;
      return stream;
    }

    // _service builds its own agent without the stream function — rebuild
    // inline (kept explicit so the test reads top-to-bottom).
    await tester.runAsync(() async {
      final partial = _msg(
        [const TextContent(text: 'ответ\nm2')],
        service.agent.state.model,
      );
      // Feed through the agent's own stream: the reply ends with an
      // undecided line-start tail (`m2`, no trailing space) — the regex
      // contract keeps it.
      await service.sendText('question');
      service.agent;
      live!
        ..push(StartEvent(partial: _msg(const [], service.agent.state.model)))
        ..push(TextDeltaEvent(contentIndex: 0, delta: 'ответ\nm2', partial: partial))
        ..push(DoneEvent(reason: StopReason.stop, message: partial));
      live!.end();
      await service.waitForIdle();
    });
    await tester.pump();
    final answer = service.messages
