Future<void> sendText(String text) async {
  final trimmed = text.trim();
  if (trimmed.isEmpty) return;
  // GOAL #2394 (D8/D9): a user turn advanced the hysteresis clock; a
  // post-run hand-over still in flight is AWAITED here, before the
  // streaming check and the prompt — its records land before the run's
  // pre-flight measures the transcript. Awaited ONLY while a compaction
  // is in flight: an idle gate must not open an async gap before the
  // prompt (hosts observe `unawaited(sendText())` through
  // `waitForIdle()`, which must see the run as started).
  //
  // The post-run call runs INSIDE the ending run's lifecycle (the agent
  // end event), so after the wait the agent may still be settling:
  // the text is a fresh PROMPT, never a steer into a finished turn —
  // it waits for the settlement, then prompts (review round 1, D9).
  handOverTrigger.onTurn();
  if (handOverTrigger.gate.isCompacting) {
    await handOverTrigger.gate.wait();
    if (_agent.state.isStreaming) await _agent.waitForIdle();
  }
  // Real user input resets the inbox wake streak (the ping-pong guard);
  // the watcher itself calls sendText with the flag set.
  if (!_inboxWakeRunning) _inboxWakePolicy.resetStreak();
  // A fresh user text gets a fresh over-window auto-continuation budget.
  _overWindowAutoResumed = false;
  _clearError();
  if (_agent.state.isStreaming) {
    _agent.steer(UserMessage.text(trimmed));
    pendingSteerTexts.add(trimmed);
    notifyListeners();
    return;
  }
  final rowProblem = _liveConnectionRowProblem();
  if (rowProblem != null) {
    error = rowProblem;
    notifyListeners();
    return;
  }
  // Wall-clock catch-up (issue #259): records that came due while the
  // host slept are swept at turn start, not at the next timer tick, so
  // the fresh turn's steering poll already sees the fired reminder.
  // Lightweight test services (pre-constructed agent) have no fabric.
  if (_subagentManager != null) {
    try {
      // Awaited so the fresh turn really does see the fired reminder
      // (issue #270); the queue isolates per-record send failures.
      await _scheduledMessages.deliverDue();
    } on Object {
      // A sweep failure must never block the user's turn.
    }
  }
  _trackProductFirstTurn();

